.sb-wf--signup { min-width: 1280px; height: 100%; }
.sb-wf--signup .sb-wf-nav-panel { width: 200px; display: flex; flex-direction: column; min-height: 680px; height: 100%; }
.sb-wf--signup .sb-wf-nav-scroll { flex: 1; display: flex; flex-direction: column; }
.sb-wf-signup-main { flex: 1; display: flex; flex-direction: column; min-width: 0; background: #fff; height: 100%; }
.sb-wf-signup-topbar { display: flex; align-items: center; gap: 12px; padding: 12px 24px; border-bottom: 1px solid #e2e8f0; background: #fff; }
.sb-wf-signup-topbar .sb-wf-search { flex: 1; max-width: 480px; margin: 0 auto; display: flex; align-items: center; padding: 8px 14px; border: 1px solid #e2e8f0; border-radius: 999px; background: #fafbfc; font-size: 11px; color: #94a3b8; }
.sb-wf-signup-topbar-actions { display: flex; align-items: center; gap: 10px; margin-left: auto; }
.sb-wf-signup-page-head { padding: 20px 28px 12px; border-bottom: 1px solid #f1f5f9; }
.sb-wf-signup-page-head .sb-wf-text--h1 { font-size: 20px; margin-bottom: 4px; }
.sb-wf-signup-body { flex: 1; display: flex; gap: 0; min-height: 520px; }
.sb-wf-signup-promo { flex: 1; display: flex; flex-direction: column; padding: 24px 28px; background: linear-gradient(135deg, #f5f3ff 0%, #faf5ff 40%, #f8fafc 100%); border-right: 1px solid #e2e8f0; }
.sb-wf-signup-form-col { flex: 0 0 380px; padding: 20px 24px; background: #f8fafc; border-right: 1px solid #e2e8f0; overflow-y: auto; }
.sb-wf-signup-benefits { flex: 0 0 200px; padding: 24px 20px; background: #fff; }
.sb-wf-signup-card { width: 100%; background: #fff; border: 1px solid #e2e8f0; border-radius: 12px; padding: 20px 18px; }
.sb-wf-signup-card-head { margin-bottom: 14px; }
.sb-wf-signup-card-head .sb-wf-subtitle { margin: 0; font-size: 11px; text-transform: none; letter-spacing: 0; color: #334155; font-weight: 700; }
.sb-wf-field { margin-bottom: 12px; }
.sb-wf-field label { display: block; font-size: 10px; font-weight: 600; color: #475569; margin-bottom: 4px; }
.sb-wf-input { display: flex; align-items: center; padding: 8px 12px; border: 1px solid #e2e8f0; border-radius: 8px; background: #fafbfc; font-size: 11px; color: #94a3b8; min-height: 34px; }
.sb-wf-input--pw { justify-content: space-between; }
.sb-wf-input-row { display: flex; gap: 6px; align-items: stretch; }
.sb-wf-input-row .sb-wf-input { flex: 1; }
.sb-wf-field-hint { font-size: 9px; color: #64748b; margin: 4px 0 0; line-height: 1.4; }
.sb-wf-field-hint--timer { color: #6366f1; font-weight: 700; float: right; }
.sb-wf-social-row { display: flex; gap: 8px; margin-bottom: 4px; }
.sb-wf-social-row .sb-wf-btn { flex: 1; padding: 10px 8px; border-radius: 8px; background: #fff; justify-content: center; }
.sb-wf-social-icon { width: 22px; height: 22px; border-radius: 4px; display: inline-flex; align-items: center; justify-content: center; font-size: 11px; font-weight: 800; }
.sb-wf-social-icon--naver { background: #03c75a; color: #fff; }
.sb-wf-social-icon--kakao { background: #fee500; color: #3c1e1e; }
.sb-wf-social-icon--google { background: #fff; border: 1px solid #e2e8f0; color: #4285f4; }
.sb-wf-divider { display: flex; align-items: center; gap: 10px; margin: 14px 0 12px; font-size: 10px; color: #94a3b8; }
.sb-wf-divider::before, .sb-wf-divider::after { content: ''; flex: 1; height: 1px; background: #e2e8f0; }
.sb-wf-check-list { display: flex; flex-direction: column; gap: 8px; margin: 14px 0; }
.sb-wf-check { display: flex; align-items: flex-start; gap: 6px; font-size: 10px; color: #64748b; line-height: 1.4; }
.sb-wf-check-box { width: 14px; height: 14px; border: 2px solid #cbd5e1; border-radius: 3px; background: #fff; flex-shrink: 0; margin-top: 1px; }
.sb-wf-check-box.is-checked { background: #6366f1; border-color: #6366f1; }
.sb-wf-check-tag { font-size: 9px; color: #94a3b8; margin-left: 2px; }
.sb-wf-btn--primary { background: #6366f1; border-color: #6366f1; color: #fff; }
.sb-wf-btn--block { display: flex; width: 100%; padding: 10px; border-radius: 8px; font-size: 11px; justify-content: center; }
.sb-wf-btn--outline-sm { padding: 8px 10px; font-size: 9px; border-radius: 8px; background: #fff; white-space: nowrap; flex-shrink: 0; align-self: stretch; display: flex; align-items: center; }
.sb-wf-signup-legal { margin-top: 12px; font-size: 9px; color: #94a3b8; line-height: 1.45; text-align: center; }
.sb-wf-feature-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 10px; margin-top: auto; padding-top: 20px; }
.sb-wf-feature-card { border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px 8px; background: rgba(255,255,255,.8); }
.sb-wf-feature-card .sb-wf-block--icon { width: 28px; height: 28px; margin-bottom: 6px; font-size: 12px; }
.sb-wf-feature-card .sb-wf-text { font-size: 10px; font-weight: 700; color: #334155; margin-bottom: 4px; }
.sb-wf-feature-card .sb-wf-caption { font-size: 9px; color: #64748b; line-height: 1.35; margin: 0; }
.sb-wf-visual { flex: 1; min-height: 200px; display: flex; flex-direction: column; margin: 12px 0; }
.sb-wf-visual-img { flex: 1; min-height: 180px; background: #f1f5f9; border: 1px solid #e2e8f0; border-radius: 8px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 6px; color: #94a3b8; font-size: 11px; font-weight: 600; text-align: center; padding: 16px; }
.sb-wf-visual-img::before { content: '✕ VISUAL'; font-size: 13px; font-weight: 700; color: #64748b; }
.sb-wf-cs-card { margin-top: auto; padding: 12px; border: 1px solid #e2e8f0; border-radius: 8px; background: #f8fafc; display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 10px; color: #64748b; }
.sb-wf-cs-card .sb-wf-block--icon { width: 28px; height: 28px; flex-shrink: 0; }
.sb-wf-benefit-list { list-style: none; margin: 0; padding: 0; }
.sb-wf-benefit-list li { display: flex; gap: 8px; align-items: center; padding: 8px 0; font-size: 10px; color: #64748b; border-bottom: 1px dotted #e2e8f0; }
.sb-wf-benefit-list li:last-child { border-bottom: none; }
.sb-wf-benefit-list .sb-wf-block--icon { width: 22px; height: 22px; font-size: 10px; flex-shrink: 0; }
.sb-wf-nav-bottom-item { margin-top: auto; }
.sb-wf-badge { display: inline-block; padding: 1px 5px; background: #fef3c7; border: 1px solid #fcd34d; border-radius: 999px; font-size: 8px; font-weight: 700; color: #b45309; }
.sb-wf-badge--dot { width: 14px; height: 14px; background: #fca5a5; border: 1px solid #f87171; border-radius: 50%; font-size: 8px; color: #fff; display: flex; align-items: center; justify-content: center; padding: 0; }
